/* Functions. */
static const OriginalRange *find_range(uint32 address)
{
    sint32 index;
    for (index = 0; index < (sint32)(sizeof(ranges) / sizeof(ranges[0])); index++)
        if (address >= ranges[index].start && address < ranges[index].end)
            return ranges + index;
    return 0;
}

void *original_tables_address(uint32 address)
{
    const OriginalRange *range = find_range(address);
    if (!range)
        return 0;
    return range->data + (address - range->start);
}

sint32 original_tables_available(uint32 address)
{
    const OriginalRange *range = find_range(address);
    if (!range)
        return 0;
    return (sint32)(range->end - address);
}

const sint32 *original_tables_mips_sine_table(void)
{
    return (const sint32 *)mips_sine_table;
}
